/* Michael Ofori M.D. Foundation — editable content and interactive concept V1.
   No real payments, storage or form submissions take place. */
const CONFIG = {
  foundation: 'Michael Ofori M.D. Foundation',
  tagline: 'Care without boundaries.',
  foundedBy: 'Dr. Michael K. Ofori, MD',
  mission: 'Our mission is to improve health and well-being by expanding access to essential medical resources, health education, charitable assistance, and community-based healthcare initiatives. We are committed to supporting underserved individuals and communities, strengthening opportunities for healthier lives, and advancing compassionate, equitable care through meaningful partnerships and charitable programs.',
  vision: 'We envision a future where every individual and community, regardless of financial or social circumstances, has the opportunity to access the healthcare resources, knowledge, and support needed to live a healthier life. Through service, education, collaboration, and charitable giving, we strive to help build stronger communities and create lasting improvements in health and well-being.'
};
// Stock images from Pexels. They are visual examples, NOT photos of foundation programs, beneficiaries or Dr. Ofori.
const IMAGES = {
  hero: 'https://images.pexels.com/photos/6129507/pexels-photo-6129507.jpeg?auto=compress&cs=tinysrgb&w=1500',
  consultation: 'https://images.pexels.com/photos/6303652/pexels-photo-6303652.jpeg?auto=compress&cs=tinysrgb&w=1500',
  doctor: 'https://images.pexels.com/photos/6098051/pexels-photo-6098051.jpeg?auto=compress&cs=tinysrgb&w=1100',
  teams: 'https://images.pexels.com/photos/6129499/pexels-photo-6129499.jpeg?auto=compress&cs=tinysrgb&w=1200',
  clinical: 'https://images.pexels.com/photos/6129242/pexels-photo-6129242.jpeg?auto=compress&cs=tinysrgb&w=1100',
  conversation: 'https://images.pexels.com/photos/6303643/pexels-photo-6303643.jpeg?auto=compress&cs=tinysrgb&w=1200',
  bedside: 'https://images.pexels.com/photos/6010782/pexels-photo-6010782.jpeg?auto=compress&cs=tinysrgb&w=1300',
  learn: 'https://images.pexels.com/photos/5452254/pexels-photo-5452254.jpeg?auto=compress&cs=tinysrgb&w=1100'
};
const FOCUS = [
 {id:'medical',index:'01',icon:'+',name:'Medical Resources',short:'Supporting pathways to essential medical supplies, equipment, and care resources.',desc:'We aspire to help narrow the gap between medical need and access by supporting resource availability and identifying opportunities for targeted healthcare assistance.',image:IMAGES.consultation,tag:'Access to essentials',opportunities:['Essential care resources','Access-oriented partnerships','Support for underserved communities']},
 {id:'education',index:'02',icon:'✳',name:'Health Education',short:'Knowledge that helps people make informed decisions about their well-being.',desc:'Health information can be an important step toward healthier choices. Our vision includes accessible education, practical learning, and connections to trusted health knowledge.',image:IMAGES.doctor,tag:'Knowledge as care',opportunities:['Accessible health information','Prevention and awareness','Community learning opportunities']},
 {id:'assistance',index:'03',icon:'♡',name:'Charitable Assistance',short:'Compassionate support that responds to real human needs.',desc:'We seek opportunities to provide charitable support to individuals and communities where healthcare-related financial and social barriers are especially difficult to overcome.',image:IMAGES.bedside,tag:'Compassion in action',opportunities:['Individual and family support','Relief of healthcare barriers','Responsible charitable initiatives']},
 {id:'community',index:'04',icon:'↗',name:'Community Health',short:'Stronger health outcomes begin with stronger local connections.',desc:'We believe healthcare progress is most meaningful when built with communities. The foundation seeks thoughtful collaborations that help advance practical, locally relevant healthcare initiatives.',image:IMAGES.teams,tag:'Community-led progress',opportunities:['Local collaboration','Community-centered health initiatives','Sustainable relationships']}
];
const STEPS = [
 {name:'Listen',copy:'Begin by understanding the people and communities a prospective initiative may serve. Meaningful support starts with listening rather than assuming.'},
 {name:'Connect',copy:'Identify reputable community partners, healthcare professionals and organizations whose knowledge can shape responsible initiatives.'},
 {name:'Act',copy:'Develop charitable and educational activities around clear needs and realistic, transparent objectives. Program specifics will be published after confirmation.'},
 {name:'Learn & Share',copy:'Document outcomes honestly, acknowledge limitations and report on what is actually achieved. Evidence will inform each next step.'}
];
const REGIONS = [
 {id:'all',name:'Global vision',headline:'Health is a shared human priority.',detail:'Our intended outlook extends across borders. The geographic scope of specific activities will be published as initiatives and partners are confirmed.',tag:'A worldwide perspective'},
 {id:'africa',name:'Africa',headline:'Listening to local priorities.',detail:'Potential future collaborations may focus on education, medical resource access and community healthcare priorities defined with local partners.',tag:'Potential collaborations'},
 {id:'americas',name:'Americas',headline:'Creating stronger connections.',detail:'We envision opportunities for charitable support and community relationships that help close gaps in access and health knowledge.',tag:'Potential collaborations'},
 {id:'asia',name:'Asia',headline:'Building with communities.',detail:'The foundation’s wider outlook allows us to explore responsible partnerships wherever local need and practical opportunity align.',tag:'Potential collaborations'},
 {id:'elsewhere',name:'Beyond',headline:'Care has no fixed boundary.',detail:'We remain open to future opportunities guided by verified need, trusted partners, and the foundation’s mission.',tag:'Open to possibilities'}
];
const ARTICLES = [
 {id:'health-literacy',tag:'Health Education',title:'Why understanding health information changes everything.',excerpt:'Good health information should not be a privilege. A reflection on access, clarity and confident decision-making.',image:IMAGES.doctor,read:'4 MIN READ',body:[
  'Health knowledge can help people ask better questions, understand choices, and participate more confidently in decisions about their well-being. But information only helps when people can access and understand it.',
  'Technical language, limited access to credible sources and differences in language or digital connectivity can make even basic health guidance difficult to navigate. Accessible education begins with acknowledging those barriers.',
  'A thoughtful community health initiative can use clear communication, trusted medical knowledge and local perspectives to make information more useful. The objective is not to replace professional medical advice, but to help people know when and how to seek it.'
 ]},
 {id:'power-of-partnerships',tag:'Partnerships',title:'The power of showing up together.',excerpt:'Lasting community well-being often depends on relationships that outlast any single project.',image:IMAGES.teams,read:'3 MIN READ',body:[
  'A sustainable charitable initiative is rarely built by one person or institution alone. Community organizations, healthcare professionals, local leaders and supporters each bring different strengths.',
  'Working collaboratively means understanding what is already happening, where gaps remain and who is best positioned to respond. It also means setting expectations clearly and sharing responsibility for outcomes.',
  'For our proposed foundation model, partnership is a principle rather than a claim about programs already delivered. We hope to build future relationships grounded in mutual respect and measurable purpose.'
 ]},
 {id:'care-with-dignity',tag:'Perspective',title:'Care begins with dignity.',excerpt:'Why compassion, respect and access belong in the same conversation about health equity.',image:IMAGES.conversation,read:'4 MIN READ',body:[
  'A person seeking care brings more than a medical need. They bring concerns, family circumstances, financial realities and a personal story that deserves respect.',
  'Supporting healthier communities requires attention to both practical barriers and how people experience care. Trust is easier to build when information is clear, choices are respected and people feel heard.',
  'Compassionate assistance is about reducing friction without reducing the person to a statistic. We believe dignity should be central to every proposed initiative.'
 ]},
 {id:'beyond-clinic',tag:'Community Health',title:'Health does not begin at the clinic door.',excerpt:'Community well-being is shaped by the knowledge, resources and support available before a medical visit.',image:IMAGES.clinical,read:'3 MIN READ',body:[
  'Many aspects of well-being are influenced by the everyday environment around people, including their access to reliable information and the practical resources needed to seek care.',
  'Community-centered thinking encourages organizations to consider not only treatment, but education, prevention, support networks and barriers that arise outside clinical settings.',
  'The foundation’s mission recognizes the value of working alongside communities to explore responses that fit their needs, rather than assuming a single model works everywhere.'
 ]}
];
const IMG = (src,alt,cls='',loading='lazy')=>`<img class="${cls}" src="${src}" alt="${alt}" loading="${loading}" decoding="async" onerror="this.style.opacity='0';this.parentElement.classList.add('photo-fallback')">`;
const eye = text=>`<span class="eyebrow">${text}</span>`;
const link = (label,url,light=false)=>`<a class="text-link${light?' text-link-light':''}" href="${url}">${label} <span aria-hidden="true">↗</span></a>`;
const button = (label,action='data-open-donate',cls='pill-btn-dark')=>`<button class="pill-btn ${cls}" type="button" ${action}>${label} <span aria-hidden="true">↗</span></button>`;
let state={area:'medical',step:0,region:'all',journalCategory:'All',journalQuery:'',tab:'volunteer',donation:{amount:100,frequency:'monthly',focus:'Where needed most'},faq:0};
const root=document.getElementById('main-content');

function donationConfigurator(location='drawer'){
 const isInline=location==='inline';
 return `<div class="${isInline?'giving-widget':'donation-main'}" data-donation-widget="${location}">
  <div class="${isInline?'donate-controls':''}">
   <div class="donate-section"><span class="field-label">Give frequency</span><div class="segmented"><button type="button" data-donate-frequency="once" class="${state.donation.frequency==='once'?'selected':''}" aria-pressed="${state.donation.frequency==='once'}">One-time</button><button type="button" data-donate-frequency="monthly" class="${state.donation.frequency==='monthly'?'selected':''}" aria-pressed="${state.donation.frequency==='monthly'}">Monthly</button></div></div>
   <div class="donate-section"><span class="field-label">Choose an amount · USD</span><div class="amount-options">${[25,50,100,250].map(a=>`<button type="button" data-donate-amount="${a}" class="${state.donation.amount===a?'selected':''}" aria-pressed="${state.donation.amount===a}">$${a}</button>`).join('')}</div></div>
   ${isInline?`<button type="button" class="pill-btn pill-btn-dark" data-open-donate>Continue <span>↗</span></button>`:''}
  </div>
  ${!isInline?`<div class="donate-section custom-row"><label class="field-label" for="custom-${location}">Or enter a custom amount (USD)</label><input id="custom-${location}" type="number" min="1" max="1000000" step="1" placeholder="Custom amount" data-custom-amount value="${[25,50,100,250].includes(state.donation.amount)?'':state.donation.amount}" /></div>
  <div class="donate-section"><label class="field-label" for="focus-${location}">Your intended area of support</label><select id="focus-${location}" data-donate-focus>${['Where needed most',...FOCUS.map(f=>f.name)].map(f=>`<option value="${f}"${state.donation.focus===f?' selected':''}>${f}</option>`).join('')}</select></div>
  <div class="donation-summary"><div><span>Your giving selection</span><strong data-donation-total>$${state.donation.amount}</strong></div><div><span data-donation-cadence>${state.donation.frequency==='monthly'?'Every month':'One-time'}</span><span>USD · Concept only</span></div></div>
  <button type="button" class="pill-btn pill-btn-dark" data-preview-payment>Preview giving summary ↗</button>
  <p class="donation-note">This is an interactive demonstration. Payment processing and donor accounts are not connected. You will not be charged.</p><div data-payment-result></div>`:`<p class="widget-foot">Interactive preview. Donations are not active.</p>`}
 </div>`;
}
const focusTiles=()=>`<div class="focus-tiles">${FOCUS.map(f=>`<button type="button" class="focus-tile ${state.area===f.id?'active':''}" data-area="${f.id}" aria-pressed="${state.area===f.id}"><span class="focus-tile-index">${f.index} <span>↗</span></span><span class="focus-tile-ico">${f.icon}</span><h3>${f.name}</h3><p>${f.short}</p></button>`).join('')}</div><div id="focus-detail-container"></div>`;
function focusDetail(){const f=FOCUS.find(x=>x.id===state.area)||FOCUS[0];return `<div class="focus-detail reveal"><div class="focus-detail-copy">${eye(f.tag)}<h3>${f.name}</h3><p>${f.desc}</p>${link('Explore this focus area','#/focus?area='+f.id,true)}</div><div class="focus-detail-photo photo-fallback">${IMG(f.image,'Illustrative stock photograph representing '+f.name)}</div></div>`;}
const globalArt=()=>`<div class="global-visual"><svg class="globe-art" viewBox="0 0 500 380" role="img" aria-label="Decorative abstract globe representing a global outlook"><defs><linearGradient id="g" x1="0" x2="1"><stop stop-color="#83b29a"/><stop offset="1" stop-color="#d7e9d8"/></linearGradient></defs><circle cx="250" cy="190" r="160" fill="none" stroke="#67978a" stroke-width="1.5"/><ellipse cx="250" cy="190" rx="82" ry="160" fill="none" stroke="#58877b"/><ellipse cx="250" cy="190" rx="135" ry="160" fill="none" stroke="#58877b"/><path d="M90 190h320M111 115h278M111 265h278" stroke="#58877b"/><g fill="url(#g)" opacity=".85"><path d="M156 98l36-16 33 17-8 26 27 22-13 19-27 1-11 24-17-10-11-36-21-20z"/><path d="M208 208l35 10 19 37-14 36-15 39-19-20-7-52z"/><path d="M275 98l45-26 45 20 13 31-27 17-3 35-24 5-8 28-29-25-19-32z"/><path d="M347 229l27 11 16 29-15 16-34-15z"/></g><circle cx="205" cy="166" r="5" fill="#e5bea2"/><circle cx="328" cy="153" r="5" fill="#e5bea2"/><circle cx="225" cy="225" r="5" fill="#e5bea2"/><path d="M205 166Q260 70 328 153M205 166Q175 214 225 225M225 225Q302 255 328 153" stroke="#b7dec5" stroke-dasharray="4 7" fill="none" opacity=".8"/></svg><div class="global-visual-note"><span>A WORLDWIDE PERSPECTIVE</span><span>ONE SHARED HUMANITY ↗</span></div></div>`;
function home(){return `<section class="hero"><div class="container hero-grid"><div class="hero-copy reveal">${eye('COMPASSION. ACCESS. POSSIBILITY.')}<h1>A healthier<br/>world begins<br/>with <em>care.</em></h1><p class="lead">Healthcare opportunity should never depend on circumstance. Together, we can work toward a world where essential resources, knowledge and compassionate support are within reach.</p><div class="hero-actions">${button('Support Our Vision')}${link('Discover our purpose','#/about')}</div><div class="hero-micro"><i></i>ROOTED IN COMPASSION. OPEN TO THE WORLD.</div></div><div class="hero-media reveal"><div class="hero-media-circle"></div><div class="hero-photo photo-fallback">${IMG(IMAGES.hero,'Stock photograph of a diverse group of healthcare professionals','', 'eager')}</div><div class="hero-stamp">Care<br/>Beyond<span>BORDERS</span></div><div class="hero-floating"><span>OUR GUIDING BELIEF</span><strong>Health is a human story.</strong><p>Every life deserves dignity and possibility.</p></div></div></div></section>
 <div class="mini-stripe"><div class="container"><span><b>01</b> Access to resources</span><span><b>02</b> Education for all</span><span><b>03</b> Compassionate support</span><span><b>04</b> Healthier communities</span></div></div>
 <section class="giving-strip"><div class="container giving-wrap"><div class="giving-intro">${eye('GIVE WITH PURPOSE')}<h3>Small acts. <em>Shared impact.</em></h3><p>See how giving could work when the foundation's donation system is connected.</p></div>${donationConfigurator('inline')}</div></section>
 <section class="section section-mission"><div class="container"><div class="mission-layout"><div class="left">${eye('THE PURPOSE THAT MOVES US')}<h2>Better health starts with <em>being seen.</em></h2></div><div class="right"><p>Every community has potential. Not every community has the same access to care.</p><p>Michael Ofori M.D. Foundation is grounded in the belief that access to healthcare resources, education, and charitable support can help create more equitable opportunities for well-being.</p>${link('More about our mission','#/about')}</div></div><div class="mission-proof"><div><strong>Access</strong><p>Reducing barriers to useful medical resources and support.</p></div><div><strong>Knowledge</strong><p>Encouraging informed decisions through health education.</p></div><div><strong>Connection</strong><p>Working toward thoughtful community partnerships.</p></div></div></div></section>
 <div class="container photo-story"><div class="photo-story-main photo-fallback">${IMG(IMAGES.consultation,'Illustrative stock photograph of a healthcare professional speaking with a patient')}<div class="photo-caption"><strong>People are at the heart of the mission.</strong><span>ILLUSTRATIVE PHOTOGRAPHY · CONCEPT PREVIEW</span></div></div><div class="photo-story-side photo-fallback">${IMG(IMAGES.doctor,'Illustrative stock photograph of a healthcare professional')}<div class="photo-caption">Knowledge creates possibilities.</div></div></div>
 <section class="section section-focus"><div class="container"><div class="section-head"><div>${eye('WHERE WE HOPE TO MAKE A DIFFERENCE')}<h2>Four areas.<br/><em>One shared purpose.</em></h2></div><p>Explore the foundation's proposed areas of focus. Specific projects will be shared as they are confirmed.</p></div>${focusTiles()}</div></section>
 <section class="statement"><div class="container">${eye('WHAT WE BELIEVE')}<h2>Compassion means more when it becomes <em>possibility.</em></h2><div class="statement-foot"><p>We envision a future where financial or social circumstances do not stand between people and the opportunity for healthier lives.</p>${link('Read our vision','#/about',true)}</div></div></section>
 <section class="section stepper-section"><div class="container stepper-grid"><div class="stepper-intro">${eye('A THOUGHTFUL APPROACH')}<h2>Good intentions.<br/><em>Better questions.</em></h2><p>Our proposed approach to foundation work begins with listening, builds through collaboration and makes room for accountability.</p>${link('Explore our approach','#/focus')}</div><div class="stepper-list">${STEPS.map((s,i)=>`<div class="stepper-step"><button data-step="${i}" type="button" aria-expanded="${i===state.step}"><span class="step-number">0${i+1}</span><span class="step-name">${s.name}</span><span class="step-toggle">${state.step===i?'−':'+'}</span></button><div class="step-content" ${state.step===i?'':'hidden'}><p>${s.copy}</p></div></div>`).join('')}</div></div></section>
 <section class="section section-global"><div class="container global-layout"><div>${eye('OUR GLOBAL OUTLOOK')}<h2>Different places.<br/><em>Shared humanity.</em></h2><p>The vision is global; specific operating locations are still to be confirmed. Explore potential areas of collaboration without assuming current programs are active there.</p><div id="home-region-tabs">${regionTabs()}</div><div id="home-region-detail">${regionDetail()}</div>${link('Explore the global outlook','#/global')}</div>${globalArt()}</div></section>
 <section class="section section-journal"><div class="container"><div class="section-head"><div>${eye('IDEAS WORTH SHARING')}<h2>Stories that <em>make us think.</em></h2></div><div class="head-actions">${link('Explore the journal','#/journal')}</div></div><div class="journal-grid">${ARTICLES.slice(0,3).map(journalCard).join('')}</div></div></section>
 <section class="section section-founder"><div class="container founder-layout"><div class="founder-graphic"><div class="founder-mark">MO</div><span class="graphic-caption">A PHYSICIAN-LED VISION · FOUNDER PHOTO TO FOLLOW</span></div><div>${eye('A VISION WITH PURPOSE')}<h2>Guided by care.<br/><em>Inspired by people.</em></h2><p class="lead">Dr. Michael K. Ofori, MD is an anesthesiologist whose name stands at the heart of the foundation's commitment to health and well-being.</p><p>The foundation seeks to extend a spirit of service beyond the clinical setting through charitable giving, health education, medical resources and community partnerships.</p><div class="founder-name"><span class="monogram">MO</span><span><strong>Dr. Michael K. Ofori, MD</strong><small>Anesthesiology · Foundation namesake</small></span></div><p class="founder-disclaimer">Founder biography is introductory concept copy pending review and approval.</p>${link('Meet the foundation','#/about')}</div></div></section>
 ${ctaSection()}`;}
function regionTabs(){return `<div class="region-tabs" role="group" aria-label="Explore prospective global regions">${REGIONS.map(r=>`<button type="button" data-region="${r.id}" class="${state.region===r.id?'active':''}" aria-pressed="${state.region===r.id}">${r.name}</button>`).join('')}</div>`;}
function regionDetail(){let r=REGIONS.find(x=>x.id===state.region)||REGIONS[0];return `<div class="region-detail reveal"><span class="field-label">${r.tag}</span><h3>${r.headline}</h3><p>${r.detail}</p></div>`;}
function ctaSection(){return `<section class="cta-section"><div class="container cta-layout"><div>${eye('THE FUTURE IS SOMETHING WE SHAPE')}<h2>Let's make room for a <em>healthier tomorrow.</em></h2></div><div class="cta-actions">${button('Explore Giving')}${link('Partner or volunteer','#/get-involved')}</div></div></section>`;}
function aboutPage(){return `<section class="page-hero"><div class="container">${eye('OUR STORY · OUR REASON WHY')}<h1>Because everyone<br/>deserves <em>the chance.</em></h1><p>Driven by the belief that care, education and opportunity should travel further than circumstance.</p></div></section><section class="section"><div class="container mission-layout"><div>${eye('A FOUNDATION WITH A HUMAN PURPOSE')}<h2>Access is more than a word. <em>It is possibility.</em></h2></div><div class="right"><p>Our work is envisioned at the intersection of compassionate healthcare and charitable action.</p><p>Our name honors the physician-led spirit behind the organization. Our outlook belongs to the individuals, families and communities the foundation hopes to support.</p></div></div></section><div class="container photo-story"><div class="photo-story-main photo-fallback">${IMG(IMAGES.teams,'Illustrative stock photograph of diverse health professionals')}<div class="photo-caption"><strong>People. Partnerships. Possibility.</strong><span>EDITORIAL STOCK IMAGE, NOT A FOUNDATION EVENT</span></div></div><div class="photo-story-side photo-fallback">${IMG(IMAGES.bedside,'Illustrative stock photograph of doctor checking on patient')}</div></div><section class="section section-focus"><div class="container"><div class="section-head"><div>${eye('WHAT GUIDES US')}<h2>Our mission.<br/><em>Our vision.</em></h2></div></div><div class="statement-cards"><article class="statement-card">${eye('01 · MISSION')}<h3>For the health of all.</h3><p>${CONFIG.mission}</p></article><article class="statement-card">${eye('02 · VISION')}<h3>A world within reach.</h3><p>${CONFIG.vision}</p></article></div></div></section><section class="section"><div class="container"><div class="section-head"><div>${eye('THE VALUES THAT MATTER')}<h2>Progress starts with <em>principles.</em></h2></div></div><div class="principles"><div class="principle"><span class="num">01</span><h3>Compassion</h3><p>Recognizing the humanity and dignity of every person seeking support.</p></div><div class="principle"><span class="num">02</span><h3>Equity</h3><p>Working toward more meaningful access regardless of social or financial circumstance.</p></div><div class="principle"><span class="num">03</span><h3>Partnership</h3><p>Valuing informed collaboration, local knowledge and transparent shared goals.</p></div></div></div></section><section class="section section-founder"><div class="container founder-layout"><div class="founder-graphic"><div class="founder-mark">MO</div><span class="graphic-caption">FOUNDER PORTRAIT PLACEHOLDER</span></div><div>${eye('THE NAME BEHIND THE FOUNDATION')}<h2>Dr. Michael K. <em>Ofori, MD.</em></h2><p class="lead">An anesthesiologist whose professional identity inspires a broader mission centered on health and compassionate support.</p><p>A fuller founder story, approved biography and original portrait will be added after consultation.</p><p class="founder-disclaimer">This section intentionally avoids unverified personal history or claims about past foundation activities.</p>${link('Connect with us','#/contact')}</div></div></section>${ctaSection()}`;}
function programPage(){const selected=FOCUS.find(x=>x.id===state.area)||FOCUS[0];return `<section class="page-hero"><div class="container">${eye('FOUR AREAS OF FOCUS')}<h1>Better health takes<br/><em>more than medicine.</em></h1><p>Explore the foundation's intended work across medical resources, knowledge, charitable assistance and community health.</p></div></section><section class="section section-focus"><div class="container"><div class="section-head"><div>${eye('INTERACTIVE FOCUS EXPLORER')}<h2>Choose an area.<br/><em>See the opportunity.</em></h2></div><p>These are proposed priority areas from the stated mission; detailed programs will be published after confirmation.</p></div>${focusTiles()}</div></section><section class="section image-section"><div class="container"><div class="section-head"><div>${eye('THE OPPORTUNITY AHEAD')}<h2>From intention<br/>to <em>action.</em></h2></div></div><div class="program-index">${FOCUS.map(f=>`<article class="program-card"><div class="program-image photo-fallback">${IMG(f.image,'Illustrative photograph representing '+f.name)}</div><div class="program-card-copy"><span class="eyebrow">${f.index} / ${f.tag}</span><h3>${f.name}</h3><p>${f.short}</p><a class="text-link" href="#/focus?area=${f.id}">Explore area <span>↗</span></a></div></article>`).join('')}</div></div></section><section class="section section-focus"><div class="container"><div class="section-head"><div>${eye('OUR WORK IS TAKING SHAPE')}<h2>Commitments before <em>claims.</em></h2></div></div><div class="transparency-grid"><article class="transparency-card"><h3>Intentional design</h3><p>We will identify goals and communities with care before describing activities as active projects.</p></article><article class="transparency-card"><h3>Local voices</h3><p>Strong collaborations are shaped with partners who understand the needs of their communities.</p></article><article class="transparency-card"><h3>Open reporting</h3><p>When program outcomes are available, we intend to share verified results rather than assumptions.</p></article></div></div></section>${ctaSection()}`;}
function globalPage(){return `<section class="page-hero page-hero-dark"><div class="container">${eye('GLOBAL OUTLOOK')}<h1>Beyond geography.<br/><em>Toward possibility.</em></h1><p>A global perspective informed by the conviction that the opportunity for good health should extend beyond borders.</p></div></section><section class="section section-global"><div class="container global-layout"><div>${eye('EXPLORE THE VISION')}<h2>The world is wide.<br/><em>Our purpose is clear.</em></h2><p>Select a region to explore potential collaboration themes. These are illustrative opportunities, not confirmed operating locations.</p><div id="global-region-tabs">${regionTabs()}</div><div id="global-region-detail">${regionDetail()}</div></div>${globalArt()}</div></section><section class="section"><div class="container"><div class="section-head"><div>${eye('OUR GUIDING PRINCIPLE')}<h2>Local understanding.<br/><em>Global compassion.</em></h2></div><p>Responsible cross-border charity begins by learning from people already working in a community.</p></div><div class="principles"><div class="principle"><span class="num">01</span><h3>Listen locally</h3><p>Understand the health needs, existing resources and lived realities of each potential community partner.</p></div><div class="principle"><span class="num">02</span><h3>Build thoughtfully</h3><p>Consider practical, mission-aligned ways to contribute knowledge, resources or charitable support.</p></div><div class="principle"><span class="num">03</span><h3>Show the work</h3><p>Share real geographic reach and documented results only when confirmed by the foundation.</p></div></div></div></section><section class="section section-focus"><div class="container"><div class="global-banner">${eye('A NOTE ON GLOBAL REACH')}<h2>This page reflects aspiration, not a map of established programs.</h2><p>Locations, local partners, current projects and measurable impact will be added only when accurate, approved information is provided.</p>${link('Explore ways to collaborate','#/get-involved',true)}</div></div></section>${ctaSection()}`;}
function journalCard(article){return `<article class="journal-card"><a class="journal-card-photo photo-fallback" href="#/journal/${article.id}" aria-label="Read ${article.title}">${IMG(article.image,'Illustrative editorial stock photograph')}</a><div class="journal-card-body"><span class="meta">${article.tag} <span>·</span> ${article.read}</span><h3>${article.title}</h3><p>${article.excerpt}</p>${link('Read the story','#/journal/'+article.id)}</div></article>`;}
function journalPage(){return `<section class="page-hero"><div class="container">${eye('NOTES FROM OUR PERSPECTIVE')}<h1>Ideas for a<br/><em>healthier world.</em></h1><p>Exploring the connection between healthcare, knowledge, community and compassion. Editorial perspectives — not claims of foundation achievements.</p></div></section><section class="section section-journal"><div class="container"><div class="search-line"><div>${eye('EXPLORE THE JOURNAL')}<h2 style="margin:12px 0 0">A little <em>perspective.</em></h2></div><label><span class="sr-only">Search journal articles</span><input type="search" id="journal-search" placeholder="Search articles..." value="${state.journalQuery.replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;')}" /></label></div><div class="journal-tools" role="group" aria-label="Filter journal category">${['All','Health Education','Partnerships','Perspective','Community Health'].map(c=>`<button type="button" data-journal-category="${c}" class="${state.journalCategory===c?'active':''}" aria-pressed="${state.journalCategory===c}">${c}</button>`).join('')}</div><div id="journal-results" class="journal-full-grid"></div></div></section>${ctaSection()}`;}
function journalArticlePage(id){const a=ARTICLES.find(x=>x.id===id);if(!a)return notFound();return `<section class="page-hero"><div class="container">${eye(a.tag.toUpperCase()+' · '+a.read)}<h1 style="max-width:1030px">${a.title}</h1><p>${a.excerpt}</p></div></section><section class="section"><div class="container article-layout"><a class="text-link" href="#/journal">← Back to journal</a><div class="article-cover photo-fallback">${IMG(a.image,'Illustrative editorial stock photo for article')}</div><span class="article-kicker">A FOUNDATION PERSPECTIVE</span><h2>Compassion begins with understanding.</h2>${a.body.map(p=>`<p>${p}</p>`).join('')}<p style="font-size:12px;color:#83958a">This article is for general education and reflection; it is not medical advice and does not document a foundation initiative.</p><div class="article-share">${link('More stories','#/journal')}<button type="button" data-copy-article="${a.id}">Copy article link ↗</button></div></div></section>${ctaSection()}`;}
function getInvolvedPage(){return `<section class="page-hero"><div class="container">${eye('GET INVOLVED')}<h1>There is room<br/>for <em>all of us.</em></h1><p>Some people bring resources. Others bring time, expertise or perspective. Every meaningful partnership starts with a conversation.</p></div></section><section class="section"><div class="container involve-layout"><div class="involve-aside">${eye('BE PART OF WHAT COMES NEXT')}<h2>A meaningful future takes <em>many hands.</em></h2><p>Explore how the foundation might welcome supporters, volunteers and community partners as its programs take shape.</p><div class="photo-fallback" style="height:285px;margin-top:30px">${IMG(IMAGES.teams,'Stock photo of diverse healthcare team')}</div><p style="font-size:10px">Illustrative photography — no affiliation implied.</p></div><div class="involve-panel"><div class="tabs-three" role="group" aria-label="Select engagement type"><button data-involve-tab="volunteer" class="${state.tab==='volunteer'?'active':''}">Volunteer</button><button data-involve-tab="partner" class="${state.tab==='partner'?'active':''}">Partner</button><button data-involve-tab="support" class="${state.tab==='support'?'active':''}">Give support</button></div><div id="involve-form-content">${involveContent()}</div></div></div></section>${ctaSection()}`;}
function involveContent(){if(state.tab==='support')return `<h3>Support the mission.</h3><p>Explore how donation options will appear when secure giving becomes active.</p><div class="donate-surface" style="padding:20px">${donationConfigurator('support')}</div>`;
const volunteer=state.tab==='volunteer';return `<h3>${volunteer?'Lend your time.':'Build a partnership.'}</h3><p>${volunteer?'Let us know how you would like to contribute. This is a preview of a future volunteer enquiry form.':'Connect around potential collaborations in healthcare education, resources or community initiatives.'}</p><form data-demo-form="${volunteer?'volunteer':'partnership'}"><div class="form-grid"><div class="form-field"><label for="first-name">Full name *</label><input id="first-name" name="fullName" required placeholder="Your full name" autocomplete="name" /></div><div class="form-field"><label for="mail">Email address *</label><input id="mail" name="email" type="email" required placeholder="you@example.com" autocomplete="email" /></div><div class="form-field"><label for="country">Country or region *</label><input id="country" name="country" required placeholder="Your region" /></div><div class="form-field"><label for="interest">${volunteer?'Area of interest':'Organization / expertise'} *</label><input id="interest" name="interest" required placeholder="${volunteer?'Health education, events...':'Your organization or expertise'}" /></div><div class="form-field full"><label for="message">Your message *</label><textarea id="message" name="message" required placeholder="Tell us a little about your interest..."></textarea></div></div><div class="form-submit"><button type="submit" class="pill-btn pill-btn-dark">Preview inquiry <span aria-hidden="true">↗</span></button><span class="demo-note">Demo form. No message will be sent.</span></div><div class="form-response" aria-live="polite"></div></form>`;}
function contactPage(){return `<section class="page-hero"><div class="container">${eye('CONTACT THE FOUNDATION')}<h1>Start a <em>conversation.</em></h1><p>Have a question, partnership idea, or interest in supporting the mission? A meaningful dialogue begins with hello.</p></div></section><section class="section"><div class="container involve-layout"><div class="involve-aside">${eye('WE WOULD LOVE TO HEAR FROM YOU')}<h2>Good things start with <em>a connection.</em></h2><p>Official contact details and social media accounts will be added once confirmed. Until then, explore the form functionality in demo mode.</p><div class="transparency-card" style="margin-top:30px;padding:27px"><h3>Contact details</h3><p>Email, mailing address and social media profiles are awaiting foundation approval. We will not publish assumed contact information.</p></div></div><div class="involve-panel"><h3>Write to us.</h3><p>Preview what the contact experience will feel like for visitors.</p><form data-demo-form="contact"><div class="form-grid"><div class="form-field"><label for="contact-name">Full name *</label><input id="contact-name" name="fullName" required autocomplete="name" placeholder="Your name"/></div><div class="form-field"><label for="contact-email">Email address *</label><input id="contact-email" type="email" name="email" required autocomplete="email" placeholder="you@example.com"/></div><div class="form-field full"><label for="contact-topic">Topic *</label><select id="contact-topic" required><option value="">Select a topic</option><option>General inquiry</option><option>Partnership inquiry</option><option>Volunteering</option><option>Giving and donations</option></select></div><div class="form-field full"><label for="contact-message">Message *</label><textarea id="contact-message" required placeholder="Tell us what is on your mind..."></textarea></div></div><div class="form-submit"><button class="pill-btn pill-btn-dark" type="submit">Preview message ↗</button><span class="demo-note">No data is transmitted or saved.</span></div><div class="form-response" aria-live="polite"></div></form></div></div></section>${ctaSection()}`;}
function donatePage(){return `<section class="page-hero page-hero-dark"><div class="container">${eye('GIVE WITH PURPOSE')}<h1>What if your gift<br/>could <em>open a door?</em></h1><p>Preview a simple, accessible donor experience built around the foundation's mission. Online payments will be enabled only after approval and integration.</p></div></section><section class="section"><div class="container donation-page-grid"><div class="donation-page-copy">${eye('BUILDING A CULTURE OF GIVING')}<h2>Make care <em>possible.</em></h2><p>Explore the structure of the giving experience, including one-time or monthly contributions and choosing a priority area.</p><p>In the future, donors could receive confirmation, receipts and updates about verified projects. Those systems are not enabled in this concept.</p><div class="empty-impact"><strong>Transparency matters.</strong><p>No funds are accepted through this version of the site.</p></div></div><div class="donate-surface">${donationConfigurator('page')}</div></div></section><section class="section section-focus"><div class="container"><div class="section-head"><div>${eye('GIVING QUESTIONS')}<h2>Clarity builds <em>trust.</em></h2></div></div><div class="faq">${[{q:'Can I donate through this website right now?',a:'Not yet. This version is a concept demonstration. No payment provider is connected, and the website does not accept or process money.'},{q:'Can I choose where my future support goes?',a:'The interface allows a visitor to select proposed focus areas. The final donation allocation rules will be established by the foundation before launch.'},{q:'Will I get a tax receipt?',a:'Receipt workflows, organization disclosures and eligibility statements will be added only after the relevant details are reviewed and approved.'},{q:'How will the foundation show its impact?',a:'We plan to publish approved descriptions, verified outcomes and real photography when that information is available. No invented achievements are shown in the demo.'}].map((q,i)=>`<div class="faq-item"><button type="button" data-faq="${i}" aria-expanded="${state.faq===i}"><span>${q.q}</span><span>${state.faq===i?'−':'+'}</span></button>${state.faq===i?`<p>${q.a}</p>`:''}</div>`).join('')}</div></div></section>`;}
function notFound(){return `<section class="page-hero"><div class="container">${eye('PAGE NOT FOUND')}<h1>Let's find the <em>right way.</em></h1><p>That page could not be found. Explore the foundation's mission and areas of focus.</p>${link('Return home','#/')}</div></section>`;}
function render(){
 let path=(location.hash||'#/').replace(/^#/,'').split('?')[0];let query=(location.hash||'').split('?')[1]||'';let params=new URLSearchParams(query);
 if(path==='/focus'&&params.get('area')&&FOCUS.some(f=>f.id===params.get('area')))state.area=params.get('area');
 if(path==='/get-involved'&&['volunteer','partner','support'].includes(params.get('tab')))state.tab=params.get('tab');
 let pageTitle='';
 if(path==='/'||path===''){root.innerHTML=home();pageTitle='Home';}
 else if(path==='/about'){root.innerHTML=aboutPage();pageTitle='Our Story';}
 else if(path==='/focus'){root.innerHTML=programPage();pageTitle='Our Focus';}
 else if(path==='/global'){root.innerHTML=globalPage();pageTitle='Global Outlook';}
 else if(path==='/journal'){root.innerHTML=journalPage();pageTitle='Journal';}
 else if(path.startsWith('/journal/')){root.innerHTML=journalArticlePage(path.split('/')[2]);pageTitle='Journal';}
 else if(path==='/get-involved'){root.innerHTML=getInvolvedPage();pageTitle='Get Involved';}
 else if(path==='/contact'){root.innerHTML=contactPage();pageTitle='Contact';}
 else if(path==='/donate'){root.innerHTML=donatePage();pageTitle='Donation Preview';}
 else{root.innerHTML=notFound();pageTitle='Page Not Found';}
 document.title=pageTitle+' | '+CONFIG.foundation;
 document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+path));
 document.querySelector('#focus-menu-trigger')?.classList.toggle('active',path==='/focus');
 refreshDynamic();closeMenu();closeSearch();closeDonation();window.scrollTo({top:0,behavior:'instant'});
}
function refreshDynamic(){document.querySelector('#focus-detail-container')?.replaceChildren(createNode(focusDetail()));document.querySelector('#journal-results')&&updateJournal();updateRegion();}
function createNode(html){const template=document.createElement('template');template.innerHTML=html.trim();return template.content.firstElementChild;}
function updateFocus(){document.querySelectorAll('[data-area]').forEach(el=>{let active=el.dataset.area===state.area;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});document.querySelector('#focus-detail-container')?.replaceChildren(createNode(focusDetail()));}
function updateSteps(){document.querySelectorAll('.stepper-step').forEach((el,i)=>{const open=i===state.step;el.querySelector('button').setAttribute('aria-expanded',String(open));el.querySelector('.step-toggle').textContent=open?'−':'+';el.querySelector('.step-content').hidden=!open;});}
function updateRegion(){document.querySelectorAll('[data-region]').forEach(b=>{const a=b.dataset.region===state.region;b.classList.toggle('active',a);b.setAttribute('aria-pressed',String(a));});['home-region-detail','global-region-detail'].forEach(id=>{document.getElementById(id)?.replaceChildren(createNode(regionDetail()));});}
function updateJournal(){const list=document.querySelector('#journal-results');if(!list)return;const q=state.journalQuery.toLowerCase().trim();const hits=ARTICLES.filter(a=>(state.journalCategory==='All'||a.tag===state.journalCategory)&&(!q||[a.title,a.excerpt,a.tag].join(' ').toLowerCase().includes(q)));list.innerHTML=hits.length?hits.map(journalCard).join(''):`<div class="empty-msg" style="grid-column:1/-1">No articles match your search. Try a broader term.</div>`;document.querySelectorAll('[data-journal-category]').forEach(b=>{let act=b.dataset.journalCategory===state.journalCategory;b.classList.toggle('active',act);b.setAttribute('aria-pressed',String(act));});}
function updateDonateWidgets(){document.querySelectorAll('[data-donate-amount]').forEach(b=>{let a=+b.dataset.donateAmount===state.donation.amount;b.classList.toggle('selected',a);b.setAttribute('aria-pressed',String(a));});document.querySelectorAll('[data-donate-frequency]').forEach(b=>{let a=b.dataset.donateFrequency===state.donation.frequency;b.classList.toggle('selected',a);b.setAttribute('aria-pressed',String(a));});document.querySelectorAll('[data-donate-focus]').forEach(s=>s.value=state.donation.focus);document.querySelectorAll('[data-donation-total]').forEach(el=>el.textContent='$'+state.donation.amount.toLocaleString('en-US'));document.querySelectorAll('[data-donation-cadence]').forEach(el=>el.textContent=state.donation.frequency==='monthly'?'Every month':'One-time');}
const donationShell=document.getElementById('donate-shell');const searchShell=document.getElementById('search-shell');let previouslyFocused=null;
function openDonation(){previouslyFocused=document.activeElement;document.getElementById('drawer-donation').innerHTML=donationConfigurator('drawer');donationShell.classList.add('open');donationShell.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';donationShell.querySelector('.icon-close').focus();}
function closeDonation(){donationShell.classList.remove('open');donationShell.setAttribute('aria-hidden','true');if(!searchShell.classList.contains('open'))document.body.style.overflow='';}
const SEARCH_DATA=[{text:'Home',url:'#/'},{text:'Our mission and vision',url:'#/about'},{text:'Medical resources',url:'#/focus?area=medical'},{text:'Health education',url:'#/focus?area=education'},{text:'Charitable assistance',url:'#/focus?area=assistance'},{text:'Community health',url:'#/focus?area=community'},{text:'Global outlook',url:'#/global'},{text:'Journal',url:'#/journal'},{text:'Volunteer',url:'#/get-involved?tab=volunteer'},{text:'Partner with us',url:'#/get-involved?tab=partner'},{text:'Giving preview',url:'#/donate'},{text:'Contact the foundation',url:'#/contact'}];
function updateSearchResults(q=''){const el=document.getElementById('search-results');const hits=SEARCH_DATA.filter(x=>x.text.toLowerCase().includes(q.toLowerCase())).slice(0,8);el.innerHTML=hits.length?hits.map(x=>`<a class="search-result" href="${x.url}">${x.text}<small>View ↗</small></a>`).join(''):'<p class="smallcopy">No results found. Try “health”, “mission” or “volunteer”.</p>';}
function openSearch(){previouslyFocused=document.activeElement;searchShell.classList.add('open');searchShell.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';document.getElementById('global-search').value='';updateSearchResults();document.getElementById('global-search').focus();}
function closeSearch(){searchShell.classList.remove('open');searchShell.setAttribute('aria-hidden','true');if(!donationShell.classList.contains('open'))document.body.style.overflow='';}
function closeMenu(){const mob=document.getElementById('mobile-nav');mob.classList.remove('open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false');document.querySelector('.nav-dropdown').classList.remove('open');document.getElementById('focus-menu-trigger').setAttribute('aria-expanded','false');}
let toastTimer;function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4500);}

document.addEventListener('click',e=>{
 let target=e.target;
 let btn=target.closest('[data-open-donate]');if(btn){e.preventDefault();openDonation();return;}
 if(target.closest('[data-close-donate]')){closeDonation();return;}
 if(target.closest('[data-search-close]')){closeSearch();return;}
 if(target.closest('[data-area]')){state.area=target.closest('[data-area]').dataset.area;updateFocus();return;}
 if(target.closest('[data-step]')){state.step=+target.closest('[data-step]').dataset.step;updateSteps();return;}
 if(target.closest('[data-region]')){state.region=target.closest('[data-region]').dataset.region;updateRegion();return;}
 if(target.closest('[data-journal-category]')){state.journalCategory=target.closest('[data-journal-category]').dataset.journalCategory;updateJournal();return;}
 if(target.closest('[data-involve-tab]')){state.tab=target.closest('[data-involve-tab]').dataset.involveTab;document.getElementById('involve-form-content').innerHTML=involveContent();document.querySelectorAll('[data-involve-tab]').forEach(b=>b.classList.toggle('active',b.dataset.involveTab===state.tab));return;}
 if(target.closest('[data-donate-amount]')){state.donation.amount=+target.closest('[data-donate-amount]').dataset.donateAmount;updateDonateWidgets();document.querySelectorAll('[data-custom-amount]').forEach(el=>el.value='');return;}
 if(target.closest('[data-donate-frequency]')){state.donation.frequency=target.closest('[data-donate-frequency]').dataset.donateFrequency;updateDonateWidgets();return;}
 if(target.closest('[data-preview-payment]')){const el=target.closest('[data-donation-widget]').querySelector('[data-payment-result]');if(el)el.innerHTML=`<div class="donation-example"><strong>Your giving selection is ready for review.</strong><br/>$${state.donation.amount.toLocaleString('en-US')} USD · ${state.donation.frequency==='monthly'?'Monthly':'One-time'} · ${state.donation.focus}.<br/><strong>Demo only:</strong> no payment has been requested, processed or collected.</div>`;return;}
 if(target.closest('[data-faq]')){const id=+target.closest('[data-faq]').dataset.faq;state.faq=state.faq===id?-1:id;const scroll=window.scrollY;const panel=target.closest('.faq');const list=[{q:'Can I donate through this website right now?',a:'Not yet. This version is a concept demonstration. No payment provider is connected, and the website does not accept or process money.'},{q:'Can I choose where my future support goes?',a:'The interface allows a visitor to select proposed focus areas. The final donation allocation rules will be established by the foundation before launch.'},{q:'Will I get a tax receipt?',a:'Receipt workflows, organization disclosures and eligibility statements will be added only after the relevant details are reviewed and approved.'},{q:'How will the foundation show its impact?',a:'We plan to publish approved descriptions, verified outcomes and real photography when that information is available. No invented achievements are shown in the demo.'}];panel.innerHTML=list.map((q,i)=>`<div class="faq-item"><button type="button" data-faq="${i}" aria-expanded="${state.faq===i}"><span>${q.q}</span><span>${state.faq===i?'−':'+'}</span></button>${state.faq===i?`<p>${q.a}</p>`:''}</div>`).join('');window.scrollTo({top:scroll,behavior:'instant'});return;}
 if(target.closest('[data-copy-article]')){const id=target.closest('[data-copy-article]').dataset.copyArticle;const url=location.href.split('#')[0]+'#/journal/'+id;if(navigator.clipboard?.writeText)navigator.clipboard.writeText(url).then(()=>toast('Article link copied.'),()=>toast('Copy the current page URL to share.'));else toast('Copy the current page URL to share.');return;}
 if(target.closest('#menu-toggle')){const nav=document.getElementById('mobile-nav');const open=!nav.classList.contains('open');nav.classList.toggle('open',open);document.getElementById('menu-toggle').setAttribute('aria-expanded',String(open));return;}
 if(target.closest('#search-open')){openSearch();return;}
 if(target.closest('#focus-menu-trigger')){const menu=document.querySelector('.nav-dropdown');const open=!menu.classList.contains('open');menu.classList.toggle('open',open);document.getElementById('focus-menu-trigger').setAttribute('aria-expanded',String(open));return;}
 if(target.closest('#backtop')){window.scrollTo({top:0,behavior:'smooth'});return;}
});
document.addEventListener('input',e=>{
 if(e.target.matches('#journal-search')){state.journalQuery=e.target.value;updateJournal();}
 if(e.target.matches('#global-search')){updateSearchResults(e.target.value);}
 if(e.target.matches('[data-custom-amount]')){const n=Number(e.target.value);if(e.target.value!==''&&Number.isFinite(n)&&n>=1&&n<=1000000){state.donation.amount=Math.round(n);updateDonateWidgets();}}
});
document.addEventListener('change',e=>{if(e.target.matches('[data-donate-focus]')){state.donation.focus=e.target.value;updateDonateWidgets();}});
document.addEventListener('submit',e=>{
 if(e.target.matches('#subscribe-form')){e.preventDefault();e.target.reset();toast('Preview only: newsletter sign-up is not yet connected. No email was collected.');return;}
 if(e.target.matches('[data-demo-form]')){e.preventDefault();const feedback=e.target.querySelector('.form-response');if(feedback)feedback.innerHTML='<div class="form-confirm"><strong>Preview completed.</strong> The form is validated, but it has not sent or saved any personal information. A submission service will be connected after approval.</div>';e.target.reset();return;}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(donationShell.classList.contains('open')){closeDonation();previouslyFocused?.focus();}if(searchShell.classList.contains('open')){closeSearch();previouslyFocused?.focus();}closeMenu();}});
window.addEventListener('hashchange',render);
window.addEventListener('scroll',()=>{const max=document.documentElement.scrollHeight-innerHeight;document.getElementById('scroll-progress').style.width=(max>0?100*scrollY/max:0)+'%';document.getElementById('backtop').classList.toggle('show',scrollY>650);},{passive:true});
document.getElementById('year').textContent=new Date().getFullYear();
render();
